import {newKingdom,slots,build,buildWall,expandKingdom,upgradeTower,startWave,retryWave,deployPolicy,stepKingdom,postWave,completedMission} from './kingdom-state.js';
import {drawKingdom} from './kingdom-render.js';
const $=id=>document.getElementById(id),KEY='logicade.kingdom.v1';
const lessons=[
 {id:'one',title:'A watchtower has a choice',topic:'If / else',brief:'Raise a tower. Deploy conditions that choose a shot from live threats, then stop the first wave.',guide:'Use enemy_type(), is_fast(), nearby() or mana() to select ammunition. The watchtower runs your policy repeatedly when enemies enter range.'},
 {id:'armor',title:'Stop the Iron Brutes',topic:'Comparison & conditions',brief:'Write a condition that uses cannons against armor and stop at least four Iron Brutes.',guide:'enemy_type() returns 3 for an Iron Brute. is_armored() reads its live armor. Cannons spend 4 mana; if mana runs low, fire an arrow.'},
 {id:'fast',title:'Hold the Ash Drakes',topic:'Boolean decisions',brief:'Slow at least four fast enemies with frost shots before they reach the castle.',guide:'is_fast() reads a live threat speed. Frost costs 2 mana and slows its target. Keep an else branch for when mana runs low.'},
 {id:'lanes',title:'Cover three lanes',topic:'Lane decisions',brief:'Raise watchtowers across all three lanes and fire into each lane.',guide:'lane() reports the current tower lane as 0, 1 or 2. Read it in a condition to choose a lane-specific rule. Add enough towers to cover each road.'},
 {id:'keep',title:'Protect the inner keep',topic:'Conditions & resource planning',brief:'Hold three waves with at least 150 keep health remaining.',guide:'The lanes have separate threat mixes. Build defenses across the map and use castle_health() if your policy should react to damage.'},
 {id:'victory',title:'Secure the Eastern March',topic:'Programmed strategy',brief:'Adapt your defenses and defeat all five increasingly difficult waves.',guide:'Use between-wave income to expand, upgrade towers and place roadblocks. Save mana for armored and clustered threats.'}
];
const example='if (enemy_type() == 3 && mana() >= 4) {\n    shoot("cannon");\n} else if (is_fast() && mana() >= 2) {\n    shoot("frost");\n} else if (nearby() >= 2 && mana() >= 4) {\n    shoot("cannon");\n} else {\n    shoot("arrow");\n}\n';
let game=newKingdom(),selected={lane:1,col:0},hover=null,paused=false,held=false,showing=false,last=performance.now(),uiClock=0,saveClock=0;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&[...['planning','battle','cleared','won','lost','error']].includes(saved.phase)){game={...newKingdom(),...saved};if(game.policy){const result=deployPolicy(game,game.policy);if(!result.ok)game.policy='';}}}catch{}
$('code').value=localStorage.getItem(KEY+'.code')||game.policy||example;
for(const m of lessons){const o=document.createElement('option');o.value=m.id;o.textContent=m.title;$('lesson').append(o);}let selectedLesson=localStorage.getItem(KEY+'.lesson')||'one';
function mission(){const m=lessons.find(m=>m.id===selectedLesson)||lessons[0];selectedLesson=m.id;$('lesson').value=m.id;$('lesson-title').textContent=m.topic;$('lesson-brief').textContent=m.brief;$('guidance').textContent=m.guide;}
mission();
const canvas=$('battlefield'),ctx=canvas.getContext('2d');
function save(){try{localStorage.setItem(KEY,JSON.stringify(game));localStorage.setItem(KEY+'.code',$('code').value);localStorage.setItem(KEY+'.lesson',selectedLesson);}catch{}}
function announce(text){game.message=text;}
$('lesson').onchange=()=>{selectedLesson=$('lesson').value;mission();save();};$('starter').onclick=()=>{$('code').value=example;save();};
$('code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('    ',a,b,'end');}};$('code').oninput=()=>save();
function selectedSlot(){return selected||{lane:1,col:0};}
$('tower').onclick=()=>{const p=selectedSlot(),r=build(game,'tower',p.lane,p.col);announce(r.message);save();};
$('upgrade').onclick=()=>{const p=selectedSlot(),r=upgradeTower(game,p.lane,p.col);announce(r.message);save();};
$('expand').onclick=()=>{const r=expandKingdom(game);announce(r.message);save();};
$('wall').onclick=()=>{const p=selectedSlot(),r=buildWall(game,p.lane);announce(r.message);save();};
$('dispatch').onclick=()=>{if(game.phase==='cleared'){postWave(game);}else if(game.phase==='lost'){retryWave(game);}if(game.phase==='error'&&game.policy){const d=deployPolicy(game,$('code').value);if(!d.ok){announce(d.message);return;}}
if(game.phase==='planning'){if(!game.towers.length){announce('Raise at least one watchtower first.');return;}const d=deployPolicy(game,$('code').value);if(!d.ok){announce(d.message);return;}const w=startWave(game);announce(w.message);}save();};
$('retry').onclick=()=>{retryWave(game);save();};$('deploy').onclick=()=>{const r=deployPolicy(game,$('code').value);announce(r.ok?'Policy deployed. The next wave will use these conditions.':r.message);save();};
$('pause-code').onclick=()=>{held=!held;$('pause-code').textContent=held?'Resume tower attacks':'Hold attacks';announce(held?'Towers held; enemies keep moving. Resume quickly.':'Tower policy resumed.');};
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';};
canvas.onpointermove=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*960,y=(e.clientY-r.top)/r.height*600;hover=null;for(let l=0;l<3;l++)for(let c=0;c<3;c++){const p=slots()[l][c];if(Math.hypot(x-p.x,y-p.y)<29)hover=p;}};canvas.onpointerleave=()=>{hover=null;};canvas.onclick=()=>{if(hover){selected={lane:hover.lane,col:hover.col};if(game.phase!=='battle'&&game.phase!=='error'&&hover.col<=(game.expanded?2:1)&&!game.towers.some(t=>t.lane===hover.lane&&t.col===hover.col)){const r=build(game,'tower',hover.lane,hover.col);announce(r.message);}else if(hover.col===2&&!game.expanded)announce('Claim the Eastern Ridge to build on these high-ground positions.');save();}};
function drawUI(){const remain=game.castleHP/game.maxCastleHP;$('hud').innerHTML=`<span><strong>${game.wave}/${5}</strong>Wave</span><span><strong>${game.coins}</strong>Treasury</span><span><strong>${Math.floor(game.mana)}/${game.maxMana}</strong>Mana</span><span><strong>${Math.ceil(game.castleHP)}/${game.maxCastleHP}</strong>Keep</span><span><strong>${game.totals.kills}</strong>Stopped</span><span><strong>${game.totals.leaked}</strong>Breaches</span>`;$('message').textContent=game.message;
let count=0;for(const m of lessons)if(completedMission(game,m.id))count++;$('mission-count').textContent=`${count}/6`;$('dispatch').disabled=paused||['battle','won','lost'].includes(game.phase);$('dispatch').textContent=game.phase==='cleared'?'Plan next wave':game.phase==='won'?'Kingdom secure':game.phase==='lost'?'Reinforce, then retry':game.phase==='error'?'Repair policy & resume':'Deploy policy & dispatch wave';$('retry').hidden=game.phase!=='lost';$('tower').disabled=game.phase==='battle'||game.coins<45;$('expand').disabled=game.phase==='battle'||game.expanded||game.coins<80;$('upgrade').disabled=game.phase==='battle'||!game.towers.some(t=>t.lane===selected?.lane&&t.col===selected?.col);$('wall').disabled=game.phase==='battle'||game.walls.some(w=>w.lane===(selected?.lane??0))||game.coins<30;
$('policy-status').textContent=game.phase==='error'?game.policyError:game.phase==='battle'?(held?'Towers held · enemies still advance.':`Wave ${game.wave} underway · ${game.queue.length} attackers still marching.`):game.policy?'Policy deployed. Edit it, then deploy your changes before the next wave.':'Place a tower, choose your ammunition rules and deploy the policy.';
$('record').textContent=`Waves held: ${game.stars}/5\nShots: ${game.totals.shots}\nArrows: ${game.totals.shotTypes.arrow} · Frost: ${game.totals.shotTypes.frost} · Cannons: ${game.totals.shotTypes.cannon}\nArmored enemies hit by cannon: ${game.totals.armoredHits} · Brutes stopped: ${game.totals.brutesStopped}\nEnemies stopped: ${game.totals.stopped}\nKeep breaches: ${game.totals.breaches}\nBranch checks: ${game.totals.branches}`;
[...$('lesson').options].forEach(o=>{const m=lessons.find(m=>m.id===o.value);o.textContent=`${m&&completedMission(game,m.id)?'✓ ':''}${m?.title||o.textContent}`;});$('kingdom-state').replaceChildren(...[0,1,2].map(l=>{const span=document.createElement('span');const t=game.towers.filter(t=>t.lane===l).length;const w=game.walls.some(w=>w.lane===l);span.textContent=`${['North','Middle','South'][l]} lane · ${t} towers${w?' · roadblock':''}`;return span;}));$('log').replaceChildren(...game.ledger.slice(-8).reverse().map(e=>{const li=document.createElement('li');li.textContent=e.message;return li;}));}
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!paused&&!document.hidden){if(game.phase==='battle')stepKingdom(game,dt,held?null:game.ast);uiClock+=dt;saveClock+=dt;}drawKingdom(ctx,game,hover,selected);if(uiClock>.15){drawUI();uiClock=0;}if(saveClock>2){save();saveClock=0;}requestAnimationFrame(frame);}
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});drawUI();requestAnimationFrame(frame);
